    ('823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Quiz — Une méthode, toujours la même, en cinq gestes', 'Physique-Chimie', 'Tle', 'Appliquer la deuxième loi de Newton', 'd4350d5c-1a54-5335-938e-9307fd74154a'::uuid),
    ('3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'Quiz — Une parabole, qu’il s’agisse d’un ballon ou d’un électron', 'Physique-Chimie', 'Tle', 'Mouvement dans un champ uniforme', '432ed188-12bb-582f-98b4-cd16a9ab0c31'::uuid),
    ('706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Quiz — Tomber sans jamais toucher le sol', 'Physique-Chimie', 'Tle', 'Mouvement dans un champ de gravitation', '7ef2619b-0cc4-5eea-adba-ea8884ea264d'::uuid),
    ('936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Quiz — Là où le fluide accélère, la pression tombe', 'Physique-Chimie', 'Tle', 'Écoulement d’un fluide incompressible', '6f7487f5-aeb1-5122-9e1a-6d934e13ba38'::uuid),
    ('0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'Quiz — Deux échelles pour un même objet', 'Physique-Chimie', 'Tle', 'Description d’un système thermodynamique', 'aa7eb2f9-451f-50ef-b17d-32ce41718a41'::uuid),
    ('3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Quiz — Chauffer, ou changer d’état : deux factures différentes', 'Physique-Chimie', 'Tle', 'Variation de l’énergie interne d’un système', '892cf763-6fe9-5787-a15d-01694546cbfe'::uuid),
    ('07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Quiz — Rien ne se perd : tout se compte', 'Physique-Chimie', 'Tle', 'Le premier principe de la thermodynamique', '05927899-c0a4-5456-87e3-70890c1196c1'::uuid),
    ('480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Quiz — Trois façons de passer du chaud au froid', 'Physique-Chimie', 'Tle', 'Transferts thermiques', '148f66c8-6095-5420-b056-139a54ac0d4c'::uuid),
    ('71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Quiz — Pourquoi l’échelle des décibels n’est pas une échelle ordinaire', 'Physique-Chimie', 'Tle', 'L’intensité sonore', 'c77c582f-b716-5199-a731-3ca80a8b88e6'::uuid),
    ('8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'Quiz — La fréquence dépend de qui bouge', 'Physique-Chimie', 'Tle', 'L’effet Doppler', 'b05c23cb-461d-5283-a99f-31331e07ad2a'::uuid),
    ('80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'Quiz — Ce qui prouve qu’une onde est une onde', 'Physique-Chimie', 'Tle', 'Diffraction d’une onde', '2459edc7-b39d-5b23-a21f-0f5923d7bc3e'::uuid),
    ('738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Quiz — Deux lumières qui donnent de l’ombre', 'Physique-Chimie', 'Tle', 'Interférences de deux ondes', '74b1763f-eff5-56a6-9225-c81c59097abd'::uuid),
    ('d62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Quiz — Deux lentilles, un foyer commun, et le ciel s’agrandit', 'Physique-Chimie', 'Tle', 'Système optique et formation d’images : la lunette astronomique', '4ed0c68b-aa9d-5b7b-b538-c470c9e05ecf'::uuid),
    ('1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Quiz — Une onde qui arrive par paquets', 'Physique-Chimie', 'Tle', 'Modèle corpusculaire de la lumière : le photon', '7df9974b-265d-551d-8ba1-8d2102fe388f'::uuid),
    ('a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'Quiz — Le temps qu’il faut à un condensateur pour se remplir', 'Physique-Chimie', 'Tle', 'Dynamique d’un circuit électrique et capteurs capacitifs', '4497a241-a678-5819-b148-a0f8fc7d7040'::uuid)
  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('2cb0b238-1405-552d-a737-f9e3c1fd7875'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Selon Brönsted, un acide est une espèce qui…', 'mcq', '["Cède un proton H⁺","Capte un proton H⁺","Cède un électron","Libère un ion HO⁻"]'::jsonb, 0, 'La base, elle, capte le proton. La définition ne parle ni d’électron ni de HO⁻.', 1),
    ('6e08c8cb-79ac-516e-bfa0-0c23854715d9'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Quelle est la base conjuguée de l’acide éthanoïque CH₃COOH ?', 'mcq', '["CH₃COO⁻","CH₃COOH₂⁺","CH₃OH","CH₃CO⁻"]'::jsonb, 0, 'L’acide perd son proton : CH₃COOH = CH₃COO⁻ + H⁺.', 2),
    ('6523cded-5f90-565f-9500-31223d6f2b2f'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Une espèce amphotère peut jouer le rôle d’acide ET de base.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’eau est le cas type : acide du couple H₂O/HO⁻, base du couple H₃O⁺/H₂O.', 3),
    ('2e7a0ebe-6a74-5d64-869c-6225555253a7'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Dans une réaction acido-basique, que s’échangent les réactifs ?', 'mcq', '["Un proton H⁺","Un électron","Un neutron","Une molécule d’eau"]'::jsonb, 0, 'Le transfert d’électron, lui, définit une réaction d’oxydoréduction.', 4),
    ('e8ce5b34-eb84-5e9e-9611-340a0e460240'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Pourquoi écrit-on H₃O⁺ plutôt que H⁺ dans les équations en solution aqueuse ?', 'mcq', '["Le proton est aussitôt fixé par une molécule d’eau","Parce que H⁺ n’a pas de charge","Par convention d’écriture des manuels","Parce que l’eau est un acide fort"]'::jsonb, 0, 'Le proton libre n’existe pas en solution : il donne l’ion oxonium H₃O⁺.', 5),
    ('8c820387-00c8-5991-b663-4924d64585a8'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'L’équation 2 H₂O = H₃O⁺ + HO⁻ porte le nom de…', 'mcq', '["Autoprotolyse de l’eau","Électrolyse de l’eau","Dissolution de l’eau","Hydrolyse acide"]'::jsonb, 0, 'Elle explique la présence simultanée de H₃O⁺ et HO⁻ dans toute solution aqueuse.', 6),
    ('eca299d3-3639-56be-be8e-983a0969e514'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'NH₄⁺ et NH₃ forment un couple acide/base.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'NH₄⁺ = NH₃ + H⁺ : NH₄⁺ est l’acide, NH₃ la base conjuguée.', 7),
    ('00f5561a-fc47-5bd4-9f95-4a7caadf45a1'::uuid, '55becbab-2d3c-5c37-b08e-b31526d560db'::uuid, 'Une demi-équation acido-basique s’écrit sous la forme…', 'mcq', '["AH = A⁻ + H⁺","AH = A⁻ + e⁻","AH + H₂O = A⁻","A⁻ = AH + HO⁻"]'::jsonb, 0, 'Elle isole le proton, qui sera pris en charge par la base de l’autre couple.', 8),
    ('af75ad98-1f5b-515b-8369-2a2916bee8d9'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Quelle relation donne [H₃O⁺] à partir du pH ?', 'mcq', '["[H₃O⁺] = c° × 10^(−pH)","[H₃O⁺] = c° × 10^(pH)","[H₃O⁺] = pH / 14","[H₃O⁺] = c° × ln(pH)"]'::jsonb, 0, 'C’est la relation réciproque de pH = −log([H₃O⁺]/c°).', 1),
    ('ca6dd2c5-9a1e-5f04-85ca-350b3786f4d8'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Une solution de pH 3 est combien de fois plus concentrée en H₃O⁺ qu’une solution de pH 5 ?', 'mcq', '["100 fois","2 fois","10 fois","1000 fois"]'::jsonb, 0, 'Deux unités de pH = deux puissances de dix.', 2),
    ('85eff2f9-3fa7-51af-a261-d92a549af887'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Que vaut le produit ionique de l’eau Ke à 25 °C ?', 'mcq', '["1,0 × 10⁻¹⁴","1,0 × 10⁻⁷","1,0 × 10⁻¹","14"]'::jsonb, 0, 'Soit pKe = 14,0. C’est lui qui fixe la neutralité à pH 7,0 à cette température.', 3),
    ('23b2f4cc-9488-54ff-aa77-bbf2d9ec36bf'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Une solution basique ne contient aucun ion H₃O⁺.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le produit ionique impose leur présence : ils sont seulement moins nombreux que les HO⁻.', 4),
    ('2e82c417-2d16-5c36-b303-c565b7f0f542'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'On dilue dix fois une solution d’acide chlorhydrique de pH 2. Le nouveau pH vaut environ…', 'mcq', '["3","1","20","7"]'::jsonb, 0, 'Diluer 10 fois un acide fort augmente le pH d’une unité.', 5),
    ('64eb1a34-fd70-524b-a300-677f55595c4b'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Pourquoi le pH de neutralité vaut-il 7,0 seulement à 25 °C ?', 'mcq', '["Parce que Ke dépend de la température","Parce que les pH-mètres sont réglés à 25 °C","Parce que l’eau gèle en dessous","Ce n’est pas vrai, il vaut toujours 7,0"]'::jsonb, 0, 'La neutralité est définie par [H₃O⁺] = [HO⁻], donc par pH = pKe/2, qui varie avec T.', 6),
    ('08f1bbcc-22d0-57ab-84ec-6da32dda3164'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Combien de décimales un pH mesuré a-t-il de sens expérimental ?', 'mcq', '["Une seule","Trois","Aucune","Autant que l’affichage en donne"]'::jsonb, 0, 'Le dixième d’unité correspond déjà à environ 2 % sur la concentration.', 7),
    ('8b2309a3-4052-5cac-af6f-ba79f6136fc8'::uuid, '8953758c-b874-59e3-b905-880918f6488f'::uuid, 'Avant une série de mesures, un pH-mètre doit être étalonné avec des solutions tampon.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Au moins deux, encadrant la zone de mesure : la sonde dérive avec le temps.', 8),
    ('451a9e7d-69ab-59a4-a67a-9044431e2eed'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Quelle est l’unité de la conductivité σ ?', 'mcq', '["S·m⁻¹","S","S·m²·mol⁻¹","Ω"]'::jsonb, 0, 'Le siemens seul est l’unité de la conductance G ; S·m²·mol⁻¹ celle de λ.', 1),
    ('69d6773c-a822-5dfe-b049-55704a1ead76'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'La conductance G dépend de la géométrie de la cellule de mesure.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'G = σ × S/L. La conductivité σ, elle, ne dépend que de la solution.', 2),
    ('c2d7e595-214d-5a8c-aa5b-03dbb64cf5b1'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Que dit la loi de Kohlrausch ?', 'mcq', '["La conductivité est la somme des contributions de chaque ion","La conductivité est proportionnelle au pH","La conductance est inversement proportionnelle à la concentration","Tous les ions ont la même conductivité molaire"]'::jsonb, 0, 'σ = Σ λᵢ[Xᵢ], valable en solution diluée.', 3),
    ('a0928969-91e9-50d1-8731-46ebd9542292'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Dans la loi de Kohlrausch, en quelle unité entrent les concentrations ?', 'mcq', '["mol·m⁻³","mol·L⁻¹","g·L⁻¹","mol"]'::jsonb, 0, 'Piège classique : 1 mol·L⁻¹ = 10³ mol·m⁻³.', 4),
    ('dc953670-9af9-5339-858b-d74f7c0e5077'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Quels ions conduisent le mieux le courant en solution aqueuse ?', 'mcq', '["H₃O⁺ et HO⁻","Na⁺ et Cl⁻","Ca²⁺ et SO₄²⁻","Tous conduisent également"]'::jsonb, 0, 'Ils se déplacent par relais de proton entre molécules d’eau, d’où un λ environ 5 fois plus grand.', 5),
    ('883d281b-81be-5110-ad71-4ca9fdcc042b'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Comment repère-t-on l’équivalence sur un titrage conductimétrique ?', 'mcq', '["À la rupture de pente entre deux segments de droite","Au maximum de la courbe","Au changement de couleur","À l’annulation de la conductivité"]'::jsonb, 0, 'On trace les deux droites et on lit leur intersection.', 6),
    ('74a7e4b7-b3fa-5f30-b338-295ea32ff140'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Le titrage conductimétrique est adapté à une solution colorée ou trouble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un indicateur coloré y serait invisible ; la conductivité, elle, se mesure quand même.', 7),
    ('5e5bf7fb-bb38-5061-9138-0d76a8a3986c'::uuid, 'ca339620-05b5-5015-a087-020d77f58bb3'::uuid, 'Pourquoi travailler avec un grand volume dans le bécher lors d’un titrage conductimétrique ?', 'mcq', '["Pour limiter l’effet de dilution par la solution titrante","Pour accélérer la réaction","Pour économiser du réactif","Pour élever la température"]'::jsonb, 0, 'Sans cela, la dilution courbe les segments qu’on veut droits.', 8),
    ('0c54bd6b-0105-5820-afe5-16fdf75454e4'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'Que relie la loi de Beer-Lambert ?', 'mcq', '["L’absorbance et la concentration","L’absorbance et la température","La conductivité et la concentration","Le pH et l’absorbance"]'::jsonb, 0, 'A = ε × ℓ × c, pour une solution diluée et à une longueur d’onde fixée.', 1),
    ('9c6ddcb7-8e37-5b40-a5f0-9b994100c8cb'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'À quelle longueur d’onde effectue-t-on une mesure d’absorbance ?', 'mcq', '["À λ_max, où l’absorption est maximale","À 500 nm systématiquement","À la longueur d’onde de la couleur de la solution","À n’importe quelle longueur d’onde"]'::jsonb, 0, 'C’est là que la mesure est la plus sensible et la moins affectée par un léger décalage.', 2),
    ('d0ad75e1-731f-50a9-a511-855b6b576fdf'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'Une solution bleue absorbe principalement…', 'mcq', '["Dans l’orange","Dans le bleu","Dans le vert","Dans l’ultraviolet"]'::jsonb, 0, 'Une solution laisse passer sa couleur et absorbe la couleur complémentaire.', 3),
    ('9476869a-bbf4-59bf-8885-7f78a6e6ee60'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'La droite d’étalonnage A = f(c) doit passer par l’origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une solution de concentration nulle n’absorbe pas — d’où le réglage préalable du « blanc ».', 4),
    ('be23db04-4ada-5cdb-bcbe-3ea6d03a1bfd'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'Quelle spectroscopie identifie les groupes caractéristiques d’une molécule ?', 'mcq', '["L’infrarouge","L’UV-visible","La RMN du carbone uniquement","La spectroscopie de masse"]'::jsonb, 0, 'L’IR sonde les vibrations des liaisons : chaque groupe donne une bande à un nombre d’onde tabulé.', 5),
    ('39d84958-683c-5045-8a89-bb7b11d87315'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'En RMN du proton, que lit-on sur la courbe d’intégration ?', 'mcq', '["Le nombre d’hydrogènes du groupe","Le nombre de voisins","La masse molaire","Le déplacement chimique"]'::jsonb, 0, 'La multiplicité donne les voisins (règle des n+1), le déplacement chimique donne l’environnement.', 6),
    ('20ad876f-f6a7-5655-87e9-adc08343cb64'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'Un signal RMN qui se présente en triplet indique combien d’hydrogènes voisins ?', 'mcq', '["Deux","Trois","Un","Quatre"]'::jsonb, 0, 'Règle des (n+1)-uplets : 3 pics = 2 voisins.', 7),
    ('e0161799-bc50-5548-8d1d-8e66e3b1828c'::uuid, '8f669ecc-39cc-59c7-8faf-f983ede4de04'::uuid, 'La loi de Beer-Lambert reste valable quelle que soit la concentration.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle décroche pour les solutions concentrées, au-delà d’une absorbance d’environ 2.', 8),
    ('e1ed5449-b3b1-5319-bd5c-122c386521b9'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'Pourquoi écrit-on un signe moins dans v = −d[A]/dt pour un réactif ?', 'mcq', '["Pour que la vitesse reste positive malgré la disparition de A","Parce que la concentration est négative","Pour convertir en mol·L⁻¹","C’est une erreur d’écriture fréquente"]'::jsonb, 0, '[A] décroît, donc sa dérivée est négative : le signe moins rétablit une vitesse positive.', 1),
    ('cfa89d67-2e8c-517c-966d-9d7e1111f166'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'Comment lit-on la vitesse de réaction sur la courbe [A] = f(t) ?', 'mcq', '["C’est le coefficient directeur de la tangente","C’est l’ordonnée à l’origine","C’est l’aire sous la courbe","C’est la valeur finale de [A]"]'::jsonb, 0, 'La vitesse est une dérivée : elle se lit sur la pente, pas sur la hauteur.', 2),
    ('b30f6f66-393f-5975-a3f9-2501d79f3cd5'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'La vitesse d’une réaction est maximale…', 'mcq', '["Au début de la transformation","À la fin","Au temps de demi-réaction","Elle est constante"]'::jsonb, 0, 'Les réactifs sont alors les plus concentrés ; la courbe s’aplatit ensuite.', 3),
    ('b376f043-e7b9-520d-b1d8-058dae44e3a7'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'Que désigne le temps de demi-réaction t₁/₂ ?', 'mcq', '["La durée au bout de laquelle l’avancement atteint la moitié de sa valeur finale","La moitié de la durée totale","Le temps de disparition complète du réactif limitant","La durée d’un chauffage à reflux"]'::jsonb, 0, 'Après 5 à 7 fois t₁/₂, la transformation est pratiquement terminée.', 4),
    ('a760ee60-bea7-53fd-be4e-13ca721bff5c'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'Élever la température accélère une réaction chimique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les chocs entre entités sont plus nombreux et plus énergétiques.', 5),
    ('af5a6ed1-3874-5922-aed5-e0c3d3f90b73'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'À quoi sert la trempe lors d’un suivi par titrages successifs ?', 'mcq', '["À figer la réaction dans le prélèvement le temps du titrage","À accélérer la réaction","À colorer la solution","À étalonner le pH-mètre"]'::jsonb, 0, 'On refroidit brutalement ou on dilue : ce sont les facteurs cinétiques joués à l’envers.', 6),
    ('438fb454-97a0-5042-9016-fee7536410cf'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'Pour une réaction d’ordre 1, le temps de demi-réaction dépend de la concentration initiale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il vaut ln2/k : c’est justement la signature d’un ordre 1.', 7),
    ('bde3fdc0-986a-5bd5-aa37-61569d784f3d'::uuid, '87bd165e-1200-596e-b2d5-eb04de4cc196'::uuid, 'Un catalyseur…', 'mcq', '["Accélère la réaction sans être consommé","Déplace l’état final vers plus de produits","Est consommé en quantité stœchiométrique","Diminue la température du système"]'::jsonb, 0, 'Il n’apparaît pas dans l’équation de bilan et ne change pas l’état final.', 8),
    ('ef02517d-32e6-5de2-897a-4d866f626e1a'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Qu’est-ce qu’un acte élémentaire ?', 'mcq', '["Une étape se produisant en une seule rencontre, sans intermédiaire","L’équation de bilan de la réaction","La réaction la plus rapide du mécanisme","Un choc entre trois molécules"]'::jsonb, 0, 'Il met en jeu au plus deux entités : les chocs à trois sont trop improbables.', 1),
    ('97b4f1e0-2226-566d-9918-ad6dd97706e1'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Une flèche courbe, dans un mécanisme, représente…', 'mcq', '["Le mouvement d’un doublet d’électrons","Le déplacement d’un atome","Le sens d’évolution du système","Un transfert de proton uniquement"]'::jsonb, 0, 'Elle part du site donneur et pointe vers le site accepteur.', 2),
    ('d5936fbc-6531-500b-aabe-b5439437ef9e'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Un intermédiaire réactionnel figure dans l’équation de bilan.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Formé puis consommé, il se simplifie dans la somme des actes élémentaires.', 3),
    ('6e5c8f35-366b-55c2-92db-c82429fcc13a'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Qu’est-ce qui fait d’un atome un site accepteur ?', 'mcq', '["Une charge positive ou une charge partielle δ⁺","Un doublet non liant","Une liaison double","Une charge négative"]'::jsonb, 0, 'La polarisation vient d’une différence d’électronégativité, comme dans C=O ou C—Cl.', 4),
    ('1e4f5a74-f640-5ec8-a558-bb0b2a05000b'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Comment un catalyseur agit-il, à l’échelle microscopique ?', 'mcq', '["Il ouvre un chemin réactionnel moins coûteux en énergie","Il augmente la concentration des réactifs","Il déplace l’équilibre vers les produits","Il élève la température du milieu"]'::jsonb, 0, 'Consommé puis régénéré, il change la durée mais ni l’état final ni la constante d’équilibre.', 5),
    ('9c6aaad1-31db-5240-b9b3-d4e902716315'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Un choc efficace est un choc…', 'mcq', '["Assez énergétique et bien orienté","Entre trois entités au moins","Toujours suivi d’une réaction","Entre deux catalyseurs"]'::jsonb, 0, 'C’est l’explication microscopique des facteurs cinétiques.', 6),
    ('60c1eb3a-a82e-5d31-83d7-2990d8eb61c1'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'La somme des actes élémentaires d’un mécanisme redonne l’équation de bilan.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les intermédiaires réactionnels s’y simplifient, puisqu’ils sont formés puis consommés.', 7),
    ('ea6d3bf7-f991-5d1d-ac52-5f1711b01170'::uuid, '92836668-bbaa-5b42-969a-22084845e9f7'::uuid, 'Un doublet non liant sur un atome d’oxygène fait de lui…', 'mcq', '["Un site donneur d’électrons","Un site accepteur d’électrons","Un catalyseur","Un intermédiaire réactionnel"]'::jsonb, 0, 'Les électrons disponibles y sont : la flèche courbe part de là.', 8),
    ('40a516b3-3051-5947-9429-9ab70d335046'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'Dans la notation ᴬ_Z X, que représente Z ?', 'mcq', '["Le nombre de protons","Le nombre de neutrons","Le nombre de nucléons","La masse du noyau"]'::jsonb, 0, 'A est le nombre de nucléons ; le nombre de neutrons vaut donc A − Z.', 1),
    ('23b4aa25-3d33-5444-83fc-77e343c0aad0'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'Quelle particule est émise lors d’une désintégration α ?', 'mcq', '["Un noyau d’hélium ⁴₂He","Un électron","Un positon","Un photon"]'::jsonb, 0, 'Le noyau père perd 4 nucléons et 2 charges : ᴬ_Z X → ᴬ⁻⁴_(Z−2) Y + ⁴₂He.', 2),
    ('f1732f3b-350d-5b78-be86-74c6f4ca34b2'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'Lors d’une désintégration β⁻, que devient un neutron ?', 'mcq', '["Un proton, avec émission d’un électron","Un positon","Un noyau d’hélium","Il disparaît sans rien émettre"]'::jsonb, 0, 'Z augmente d’une unité, A ne change pas.', 3),
    ('9862c5d3-30ce-5ad5-9173-10b0cbf8cfcc'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'L’émission γ modifie le nombre de nucléons du noyau.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ni A ni Z ne changent : c’est une désexcitation, pas une désintégration.', 4),
    ('606d4ecb-1e8e-5711-8790-c93c5090f90a'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'Quelles grandeurs se conservent dans une équation nucléaire ?', 'mcq', '["Le nombre de nucléons A et la charge Z","La masse et le volume","L’énergie cinétique seule","Le nombre d’électrons"]'::jsonb, 0, 'Ce sont les lois de Soddy : elles suffisent à identifier le noyau fils.', 5),
    ('60e015e2-990e-575d-abda-11faca869368'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'La désintégration d’un noyau donné peut être prédite à l’avance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le phénomène est aléatoire : seule une population nombreuse suit une loi prévisible.', 6),
    ('1ae9bb3e-4e0a-51b1-b64a-26d558901d07'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'Qu’appelle-t-on défaut de masse d’un noyau ?', 'mcq', '["L’écart entre la masse du noyau et la somme des masses de ses nucléons séparés","La masse des neutrons manquants","La masse perdue lors d’une réaction chimique","L’erreur de mesure sur la masse"]'::jsonb, 0, 'L’énergie de liaison correspondante vaut E = Δm × c².', 7),
    ('c1d600b5-f0cd-5bfb-ace7-17c7c24ec0ac'::uuid, '38dcda81-40ed-5e5d-8285-cfafbe6ee6c1'::uuid, 'Chauffer fortement un échantillon radioactif accélère sa désintégration.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le phénomène est nucléaire : température, pression et réactions chimiques n’y changent rien.', 8),
    ('09d4d7e6-b82a-58bd-b7b2-16b998a4b48b'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Quelle est la loi de décroissance radioactive ?', 'mcq', '["N(t) = N₀ × e^(−λt)","N(t) = N₀ − λt","N(t) = N₀ / (λt)","N(t) = N₀ × λ^t"]'::jsonb, 0, 'Elle est la solution de l’équation différentielle dN/dt = −λN.', 1),
    ('c0cb0949-c3ef-55ee-be92-a1e1eb16353d'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Quelle relation lie la demi-vie t₁/₂ et la constante radioactive λ ?', 'mcq', '["t₁/₂ = ln2 / λ","t₁/₂ = λ / ln2","t₁/₂ = 2λ","t₁/₂ = 1 / λ²"]'::jsonb, 0, 'ln2 ≈ 0,693 : c’est la constante à retenir.', 2),
    ('5d375ae4-7e00-5956-a761-b8427476e459'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Après trois demi-vies, quelle fraction de l’échantillon initial subsiste ?', 'mcq', '["Un huitième","Un tiers","Un sixième","Rien"]'::jsonb, 0, 'La population est divisée par deux à chaque demi-vie : 1/2, 1/4, 1/8.', 3),
    ('d7930715-ab50-5e40-bb0f-2cdd99cdc09f'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Quelle est l’unité de l’activité d’un échantillon radioactif ?', 'mcq', '["Le becquerel (Bq)","Le sievert (Sv)","Le gray (Gy)","Le hertz (Hz)"]'::jsonb, 0, 'Un becquerel = une désintégration par seconde.', 4),
    ('2eab66e9-6dd3-55cb-98af-eea3fe5401f7'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Comment l’activité A est-elle reliée au nombre de noyaux N ?', 'mcq', '["A = λ × N","A = N / λ","A = λ / N","A = N × t₁/₂"]'::jsonb, 0, 'Elle décroît donc selon la même exponentielle que N.', 5),
    ('b32a9cab-bf77-5d05-97ea-f0e757ffb6dd'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'La demi-vie d’un noyau dépend de la quantité initiale d’échantillon.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est caractéristique du noyau, et indépendante de la quantité comme des conditions extérieures.', 6),
    ('bb794b98-94f5-5d40-b123-e0c8a3b0d870'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Pourquoi la datation au carbone 14 est-elle inutilisable au-delà de 50 000 ans environ ?', 'mcq', '["Il ne reste plus assez de ¹⁴C pour une mesure fiable","Le carbone 14 cesse de se désintégrer","Sa demi-vie change avec le temps","Les organismes anciens n’en contenaient pas"]'::jsonb, 0, 'Sa demi-vie est de 5730 ans : après une dizaine de demi-vies, il en reste moins d’un millième.', 7),
    ('aa156880-80c2-5c75-bb5a-1d1194fda1be'::uuid, 'dec0a9ba-0421-5c17-92e1-485f886ed7bb'::uuid, 'Pour dater une roche ancienne, on emploie un couple à demi-vie très longue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Uranium-plomb ou potassium-argon : leur demi-vie est à l’échelle du milliard d’années.', 8),
    ('4804f89a-4663-54aa-8db4-872ee8a9e24d'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'De quoi dépend la constante d’équilibre K ?', 'mcq', '["De la température seule","Des quantités initiales","Du volume du récipient","De la présence d’un catalyseur"]'::jsonb, 0, 'C’est ce qui la distingue du taux d’avancement final τ, propre à chaque expérience.', 1),
    ('b91dd2ac-7132-518f-9530-955333912397'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'Si Qr,i < K, dans quel sens le système évolue-t-il ?', 'mcq', '["Dans le sens direct, vers les produits","Dans le sens indirect","Il n’évolue pas","Cela dépend du catalyseur"]'::jsonb, 0, 'Le système évolue toujours de façon à rapprocher Qr de K.', 2),
    ('fa314ba6-4c93-5a0c-afa2-3749733c0dc6'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'Un solide en excès figure-t-il dans l’expression du quotient de réaction ?', 'mcq', '["Non, il n’y figure pas","Oui, avec sa masse","Oui, avec sa concentration","Seulement s’il est le réactif limitant"]'::jsonb, 0, 'Les solides et le solvant sont exclus : leur « concentration » ne varie pas.', 3),
    ('da173090-32c2-5fdc-97e9-e302c41e919b'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'À l’équilibre, les réactions directe et inverse se produisent à la même vitesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’équilibre est dynamique : seules les concentrations cessent de varier.', 4),
    ('e2c0c77b-00a2-5a1a-9748-bf53d53cea1f'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'Que vaut le taux d’avancement final d’une transformation totale ?', 'mcq', '["1","0","0,5","Il est égal à K"]'::jsonb, 0, 'τ = x_f/x_max : il vaut 1 quand la transformation va au bout.', 5),
    ('56cb410e-eb47-5551-b548-f9f19a13e2b0'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'Le quotient de réaction Qr possède une unité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les concentrations y sont divisées par c° = 1 mol·L⁻¹ : Qr est sans dimension.', 6),
    ('fc13d090-df53-5be3-b383-1b7b250b1aad'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'Diluer une solution d’acide faible modifie…', 'mcq', '["Le taux d’avancement final, mais pas K","K, mais pas le taux d’avancement","Les deux","Ni l’un ni l’autre"]'::jsonb, 0, 'K ne dépend que de la température ; τ dépend des conditions initiales.', 7),
    ('0e92c1a2-8865-5da0-8694-9925c933da11'::uuid, 'f9ef29d2-afd9-5f40-96e9-1fed91215bd0'::uuid, 'Une constante d’équilibre K de l’ordre de 10⁶ signale…', 'mcq', '["Une transformation quasi totale","Une transformation quasi nulle","Un équilibre à mi-parcours","Une réaction impossible"]'::jsonb, 0, 'Au-delà de 10⁴, la réaction peut être traitée comme totale.', 8),
    ('ae34de65-d32b-5ff4-ba37-d4ba6856ea13'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Dans une pile, l’anode est le siège de…', 'mcq', '["L’oxydation, et c’est le pôle négatif","La réduction, et c’est le pôle négatif","L’oxydation, et c’est le pôle positif","La réduction, et c’est le pôle positif"]'::jsonb, 0, 'Elle libère les électrons dans le circuit extérieur, d’où sa polarité négative.', 1),
    ('533305c5-53bd-5e60-a96f-048df35f5eeb'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'À quoi sert le pont salin ?', 'mcq', '["À fermer le circuit et assurer l’électroneutralité des compartiments","À conduire les électrons","À catalyser la réaction","À mesurer la tension"]'::jsonb, 0, 'Sans lui, les charges s’accumulent et la pile cesse immédiatement de débiter.', 2),
    ('cfec1d1e-99c3-5221-8b68-7c73095d8369'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Dans le circuit extérieur d’une pile, les électrons circulent…', 'mcq', '["De l’anode vers la cathode","De la cathode vers l’anode","Dans les deux sens","Ils ne circulent pas, seuls les ions le font"]'::jsonb, 0, 'Le courant conventionnel, lui, circule en sens inverse.', 3),
    ('c593280f-c5bb-54cb-b9c7-97472ffa27ab'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Une pile usée est un système qui a atteint son état d’équilibre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Qr = K : plus aucune évolution possible, donc plus de tension.', 4),
    ('96b39db6-184b-58db-8b71-7eb620653e4d'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Que vaut la constante de Faraday ?', 'mcq', '["96 500 C·mol⁻¹","6,02 × 10²³ mol⁻¹","1,6 × 10⁻¹⁹ C","8,31 J·K⁻¹·mol⁻¹"]'::jsonb, 0, 'C’est la charge portée par une mole d’électrons.', 5),
    ('88c94597-318a-51ed-9b73-e4282a5669c0'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Quelle relation donne la quantité d’électricité débitée ?', 'mcq', '["Q = I × Δt = n(e⁻) × F","Q = U × I","Q = n(e⁻) / F","Q = m × c × ΔT"]'::jsonb, 0, 'Elle relie la mesure électrique à l’avancement chimique.', 6),
    ('eb03ddeb-a12c-5ac5-b986-5e0c83530d42'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Un réducteur capte des électrons.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il en cède : c’est l’oxydant qui les capte.', 7),
    ('88aa0c3f-7333-5c21-bd06-5159fdd9b59d'::uuid, 'c4beff16-dd5b-5c32-9d33-c6fde338cd77'::uuid, 'Qu’est-ce qui limite la capacité d’une pile ?', 'mcq', '["Le réactif limitant de la réaction","La longueur du fil","La taille du pont salin","La température ambiante seule"]'::jsonb, 0, 'Le plus souvent le métal de l’anode qui se dissout, ou l’oxydant en solution.', 8),
    ('f42e9230-145c-5bda-bb71-e237712a347a'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Lors d’une électrolyse, l’anode est reliée à…', 'mcq', '["La borne + du générateur","La borne − du générateur","Aucune borne","Au pont salin"]'::jsonb, 0, 'Elle reste le siège de l’oxydation : seule sa polarité change par rapport à une pile.', 1),
    ('81a1e054-59fb-5197-82bd-ee6d27c3d635'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Une électrolyse fait évoluer le système…', 'mcq', '["Dans le sens qui éloigne Qr de K","Dans le sens spontané","Vers l’équilibre","Sans changer Qr"]'::jsonb, 0, 'C’est une transformation forcée : le générateur impose le sens contraire au sens naturel.', 2),
    ('7be90385-7061-5129-b376-559c43332193'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'La règle « anode = oxydation » vaut aussi bien pour une pile que pour une électrolyse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la seule règle sûre ; c’est la polarité, elle, qui s’inverse.', 3),
    ('92c89121-2127-5fcf-a596-9b6218ac6ff6'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Quelle relation donne la quantité de matière d’électrons échangés ?', 'mcq', '["n(e⁻) = I × Δt / F","n(e⁻) = F / (I × Δt)","n(e⁻) = I × F × Δt","n(e⁻) = U × I × Δt"]'::jsonb, 0, 'C’est elle qui relie la durée d’électrolyse à la masse déposée.', 4),
    ('eba91c86-d26f-53d4-b44e-4fc56d660c54'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Que produit la réduction à la cathode lors de l’électrolyse de l’eau ?', 'mcq', '["Du dihydrogène","Du dioxygène","De l’ozone","Du peroxyde d’hydrogène"]'::jsonb, 0, 'Le dioxygène se forme à l’anode, par oxydation.', 5),
    ('8c52df30-ee3e-5f81-a83f-f4a46936f1a0'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Un accumulateur fonctionne en électrolyseur pendant sa recharge.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le chargeur joue le rôle du générateur ; anode et cathode échangent leurs places.', 6),
    ('6a6ea02c-da37-5b3c-9455-f6f5d72444e4'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Qu’est-ce qui distingue une pile à combustible d’un accumulateur ?', 'mcq', '["Ses réactifs sont alimentés en continu au lieu d’être stockés","Elle ne produit pas d’électricité","Elle ne se recharge jamais","Elle fonctionne sans électrode"]'::jsonb, 0, 'Elle débite tant qu’on l’alimente en dihydrogène et en dioxygène.', 7),
    ('50064eac-deee-581c-aa7a-8161d6838b24'::uuid, '8be588e7-2ff9-5f42-841f-19b1f7d69046'::uuid, 'Par quel procédé l’aluminium est-il produit industriellement ?', 'mcq', '["Par électrolyse de l’alumine","Par distillation","Par pile à combustible","Par réduction au carbone dans un haut-fourneau"]'::jsonb, 0, 'C’est un procédé très consommateur d’énergie électrique.', 8),
    ('393e0fb5-2443-5d38-8f80-2280f5090a2f'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Un acide fort est un acide qui…', 'mcq', '["Réagit totalement avec l’eau","Est très concentré","Est très corrosif","A un pKa élevé"]'::jsonb, 0, 'Après réaction, il n’en reste plus sous forme AH dans la solution.', 1),
    ('a0f14672-4174-52f9-885a-daeaa105589d'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Plus un acide est fort, plus son pKa est…', 'mcq', '["Petit","Grand","Proche de 7","Proche de 14"]'::jsonb, 0, 'Ka est grand, donc pKa = −log Ka est petit : l’échelle est inversée.', 2),
    ('10caaf28-3112-5393-adab-16bf499b8033'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Si pH > pKa, quelle espèce du couple prédomine ?', 'mcq', '["La base A⁻","L’acide AH","Les deux à parts égales","Ni l’une ni l’autre"]'::jsonb, 0, 'La relation pH = pKa + log([A⁻]/[AH]) le donne directement.', 3),
    ('4284ff77-aca7-59c1-bdaa-74861483c1ea'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Quand pH = pKa, les deux espèces du couple ont la même concentration.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le rapport [A⁻]/[AH] vaut 1, donc son logarithme est nul.', 4),
    ('7617f14f-0993-58ed-85e3-b8386e6baad9'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Dans une solution d’acide faible, l’acide AH a entièrement disparu.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La réaction est limitée : AH et A⁻ coexistent à l’équilibre.', 5),
    ('d8ad1155-dfde-5921-9432-be9fdadcedbc'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Comment choisit-on un indicateur coloré pour un titrage ?', 'mcq', '["Sa zone de virage doit être contenue dans le saut de pH","Il doit avoir le pKa de l’acide titré","Il doit être incolore en milieu acide","N’importe quel indicateur convient"]'::jsonb, 0, 'Sinon le virage se produit ailleurs qu’à l’équivalence.', 6),
    ('029e0638-b0f1-5891-84b1-75350c4c9a68'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Quelle est la largeur approximative de la zone de virage d’un indicateur coloré ?', 'mcq', '["Environ deux unités de pH","Une demi-unité","Cinq unités","Elle est ponctuelle"]'::jsonb, 0, 'Elle est centrée sur le pKa de l’indicateur.', 7),
    ('f27a6399-98de-5c13-bda5-374a3d637146'::uuid, 'b8a0c573-4f2a-55e7-9c03-0c8f84aae1b9'::uuid, 'Que vaut le pKa du couple CH₃COOH/CH₃COO⁻ ?', 'mcq', '["4,8","2,1","9,2","14,0"]'::jsonb, 0, 'C’est un repère à connaître, avec 9,2 pour NH₄⁺/NH₃.', 8),
    ('051a2290-f339-5a8d-805a-17e510ce5658'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'Quel est le pH d’une solution d’acide fort de concentration 1,0 × 10⁻³ mol·L⁻¹ ?', 'mcq', '["3,0","11,0","1,0","7,0"]'::jsonb, 0, 'La réaction est totale : [H₃O⁺] = c, donc pH = −log c.', 1),
    ('768a4731-dc02-5d6c-b40f-6ee5727eeac9'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'À concentration égale, un acide faible donne un pH…', 'mcq', '["Plus élevé qu’un acide fort","Plus bas qu’un acide fort","Identique","Toujours égal à 7"]'::jsonb, 0, 'Sa réaction limitée libère moins d’ions H₃O⁺.', 2),
    ('73f54c10-27fe-52a9-bc39-10c60023668c'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'Qu’est-ce qu’une solution tampon ?', 'mcq', '["Un mélange d’un acide et de sa base conjuguée dont le pH varie peu","Une solution de pH exactement 7","Une solution très concentrée en acide fort","Une solution sans ions H₃O⁺"]'::jsonb, 0, 'Elle résiste aux ajouts modérés d’acide ou de base et à la dilution.', 3),
    ('4be19e1e-13a7-52e6-82c8-24714cfb663f'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'À la demi-équivalence d’un titrage d’acide faible, que vaut le pH ?', 'mcq', '["pH = pKa","pH = 7","pH = pKe/2","pH = pKa/2"]'::jsonb, 0, '[A⁻] = [AH] : c’est la méthode la plus simple pour mesurer un pKa.', 4),
    ('9155ebf0-b95a-51d2-a215-b466acd7a04b'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'À l’équivalence, les réactifs ont été mélangés dans les proportions stœchiométriques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la définition même de l’équivalence.', 5),
    ('9267ab1a-fb7d-5955-a7f3-80b833ff5dff'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'Le pH à l’équivalence d’un titrage d’acide faible par une base forte vaut 7,0.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est supérieur à 7 : la base conjuguée formée rend le milieu basique.', 6),
    ('292586cc-6dd0-55a5-9112-4ecad3023a48'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'Une solution tampon est la plus efficace quand…', 'mcq', '["[A⁻] = [AH], soit pH = pKa","l’acide est en large excès","la base est seule présente","le pH vaut 7"]'::jsonb, 0, 'C’est le point où le pH est le moins sensible à un ajout.', 7),
    ('3297bae9-e95a-53e7-b37e-28fe765de661'::uuid, 'b7da987c-3aa6-53ed-b45d-8a03e8271b84'::uuid, 'Quelles qualités doit posséder la réaction support d’un titrage ?', 'mcq', '["Totale, rapide et unique","Limitée et lente","Catalysée et réversible","Exothermique et colorée"]'::jsonb, 0, 'Sans cela, l’équivalence ne correspond pas à la quantité cherchée.', 8),
    ('bb948544-c856-55e2-b699-a4d284cc2fef'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Sur une formule topologique, que représente chaque sommet de la ligne brisée ?', 'mcq', '["Un atome de carbone","Un atome d’hydrogène","Une liaison double","Un groupe caractéristique"]'::jsonb, 0, 'Les hydrogènes portés par ces carbones sont sous-entendus.', 1),
    ('4d7fc843-5af5-5c6c-ab4d-48b6ece1724c'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Quel groupe caractéristique définit un acide carboxylique ?', 'mcq', '["—COOH","—CHO","—OH","—COO—"]'::jsonb, 0, '—CHO est l’aldéhyde, —COO— l’ester, —OH l’alcool.', 2),
    ('c25edd04-7dac-5021-b046-c3719fcc1af0'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Qu’est-ce qu’un carbone asymétrique ?', 'mcq', '["Un carbone portant quatre substituants différents","Un carbone portant une double liaison","Un carbone en bout de chaîne","Un carbone chargé positivement"]'::jsonb, 0, 'Sa présence rend la molécule chirale.', 3),
    ('43c892d8-adbd-5693-b955-b706bffe847b'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Deux énantiomères ont les mêmes propriétés physiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Mais leurs effets biologiques peuvent être très différents : les récepteurs sont eux-mêmes chiraux.', 4),
    ('a0422798-7490-563d-8225-40df1d2c038c'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'L’éthanol CH₃CH₂OH et le méthoxyméthane CH₃OCH₃ sont…', 'mcq', '["Des isomères de constitution","Des énantiomères","La même molécule","Des diastéréo-isomères"]'::jsonb, 0, 'Même formule brute C₂H₆O, enchaînement différent — ici une isomérie de fonction.', 5),
    ('04f644f4-b2b5-5773-8869-85fa7c59a9d8'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Un alcool tertiaire s’oxyde facilement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le carbone porteur du —OH n’a plus d’hydrogène à céder : il ne s’oxyde pas.', 6),
    ('e45fc54f-bc9d-51b5-8c33-009b58c7e8ea'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Quelle isomérie est possible autour d’une double liaison C=C ?', 'mcq', '["La stéréo-isomérie Z/E","L’énantiomérie","L’isomérie de chaîne","Aucune"]'::jsonb, 0, 'La double liaison ne tourne pas, ce qui fige deux dispositions distinctes.', 7),
    ('785e555e-4373-5c53-9a73-96674f5dbdac'::uuid, 'e130ed9c-e488-597f-a202-1e53a10cc784'::uuid, 'Dans un groupe carbonyle C=O, quel atome porte la charge partielle positive ?', 'mcq', '["Le carbone","L’oxygène","Les deux","Aucun, la liaison est apolaire"]'::jsonb, 0, 'L’oxygène, plus électronégatif, attire les électrons : le carbone devient site accepteur.', 8),
    ('d138ec38-102e-5fb2-b6a8-6b754ca45643'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'Comment reconnaît-on une réaction d’addition ?', 'mcq', '["Une liaison multiple disparaît au profit de liaisons simples","Un groupe en remplace un autre","Une liaison multiple apparaît","La chaîne carbonée se raccourcit"]'::jsonb, 0, 'L’élimination fait exactement l’inverse ; la substitution conserve les insaturations.', 1),
    ('6e6ab535-8820-52f8-8e87-da930f2380b9'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'Qu’est-ce que la chimiosélectivité ?', 'mcq', '["Le fait de n’attaquer qu’un seul type de groupe caractéristique","Le fait de ne réagir qu’à une seule position","Le fait de former un seul stéréo-isomère","Le fait d’utiliser un catalyseur"]'::jsonb, 0, 'La régiosélectivité vise la position, la stéréosélectivité la géométrie.', 2),
    ('bdb0ae0d-536a-52e5-8f01-e2c4f27d6e12'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'À quoi sert une protection de fonction ?', 'mcq', '["À empêcher un groupe de réagir pendant une étape","À augmenter le rendement d’une étape","À accélérer la réaction","À purifier le produit final"]'::jsonb, 0, 'On protège, on réalise l’étape voulue, puis on déprotège — deux étapes de plus.', 3),
    ('acf2432d-bda5-52a4-ac05-f48766273b59'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'Une synthèse en cinq étapes à 80 % de rendement chacune donne un rendement global d’environ…', 'mcq', '["33 %","80 %","16 %","100 %"]'::jsonb, 0, 'Les rendements se multiplient : 0,8⁵ ≈ 0,33.', 4),
    ('8bdd1021-2bfe-5ca2-945a-c798350d897b'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'Il vaut mieux placer les étapes les plus coûteuses en début de synthèse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le plus tard possible : on ne gaspille alors le réactif cher que sur la matière déjà purifiée.', 5),
    ('0e9b3e53-ad78-5219-9ac4-2fcc815ad738'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'Que mesure l’économie d’atomes ?', 'mcq', '["La part de la masse des réactifs retrouvée dans le produit voulu","Le nombre d’atomes de carbone du produit","Le coût des réactifs","Le rendement de la réaction"]'::jsonb, 0, 'C’est l’un des principes de la chimie verte.', 6),
    ('be8c4cfc-ce97-5bfc-8a1a-32634abcdc1b'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'À quoi sert un chauffage à reflux ?', 'mcq', '["À accélérer la réaction sans perdre de matière par évaporation","À purifier le produit","À séparer deux isomères","À refroidir le mélange"]'::jsonb, 0, 'Les vapeurs se condensent dans le réfrigérant et retombent dans le ballon.', 7),
    ('ce899896-c489-53e7-b8fd-78677b5315c2'::uuid, '141ada44-ad43-5911-a729-d930575d1953'::uuid, 'La protection de fonction est systématique en synthèse peptidique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seule la bonne extrémité de chaque acide aminé doit réagir : les autres sont protégées.', 8),
    ('7cc70956-10ec-5798-b15e-e5715aea881b'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Le vecteur vitesse est toujours…', 'mcq', '["Tangent à la trajectoire","Perpendiculaire à la trajectoire","Dirigé vers le centre de courbure","Vertical"]'::jsonb, 0, 'C’est le vecteur accélération qui pointe vers l’intérieur de la courbure.', 1),
    ('98ab70b8-e961-5614-b30c-874aa2fc5dcc'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Dans un mouvement circulaire uniforme, l’accélération est nulle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle vaut v²/R et pointe vers le centre : la direction de la vitesse change en permanence.', 2),
    ('e0ad654a-1ef0-5bf2-a76c-2666a64aa2f0'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Que vaut la composante normale de l’accélération ?', 'mcq', '["aₙ = v²/R","aₙ = dv/dt","aₙ = v × R","aₙ = 0 toujours"]'::jsonb, 0, 'La composante tangentielle aₜ = dv/dt traduit, elle, la variation de la valeur de la vitesse.', 3),
    ('f38bc864-d0b1-5143-a16f-793dc4eb2fe6'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Comment obtient-on l’équation de la trajectoire à partir des équations horaires ?', 'mcq', '["En éliminant le temps entre elles","En les dérivant","En les additionnant","En les intégrant"]'::jsonb, 0, 'On exprime t à partir de l’une, puis on le remplace dans l’autre.', 4),
    ('d449575c-7798-54be-9c9a-7b56e84f75e0'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Quel référentiel choisit-on pour étudier le mouvement des planètes ?', 'mcq', '["Le référentiel héliocentrique","Le référentiel terrestre","Le référentiel géocentrique","N’importe lequel"]'::jsonb, 0, 'Le géocentrique convient aux satellites de la Terre, le terrestre aux mouvements au sol.', 5),
    ('3572a27c-9d22-5908-93dd-016f5e1a160f'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Sur un pointage vidéo, comment estime-t-on la vitesse en un point ?', 'mcq', '["Par la différence finie centrée entre les points voisins","En mesurant la distance à l’origine","En dérivant deux fois la position","En divisant la distance totale par la durée totale"]'::jsonb, 0, 'v ≈ M(i−1)M(i+1) / (2τ) : c’est l’approximation de la dérivée.', 6),
    ('e4cb0c55-5212-5b47-aeba-0513ba2fd5e2'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'L’accélération est la dérivée seconde du vecteur position.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'a = dv/dt = d²OM/dt².', 7),
    ('9299e0ff-fd65-5b39-9750-8cae4c66cf0f'::uuid, 'b4bd2d54-f799-52cf-9066-154b29b5821c'::uuid, 'Un mouvement rectiligne uniforme se caractérise par…', 'mcq', '["Un vecteur accélération nul","Une accélération constante non nulle","Une vitesse nulle","Une trajectoire circulaire"]'::jsonb, 0, 'Le vecteur vitesse y est constant en valeur ET en direction.', 8),
    ('b9938a28-7a5d-5755-87eb-6fb50cb48ae8'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Quel est l’énoncé de la deuxième loi de Newton ?', 'mcq', '["ΣF = dp/dt, soit ΣF = m a à masse constante","ΣF = 0 pour tout système","F(A→B) = −F(B→A)","p = m v"]'::jsonb, 0, 'La troisième loi est celle des actions réciproques ; p = m v en est la définition.', 1),
    ('d90e5fc1-2451-5186-99e8-0a3a451f913d'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Deux forces d’interaction réciproque se compensent et le système reste immobile.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles s’appliquent à DEUX corps différents : elles ne se compensent jamais entre elles.', 2),
    ('4a54c0a5-b59d-5c32-b54a-1578bd0e7ad0'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Un système pseudo-isolé est animé d’un mouvement…', 'mcq', '["Rectiligne uniforme, ou est au repos","Circulaire uniforme","Uniformément accéléré","Toujours nul"]'::jsonb, 0, 'C’est le principe d’inertie, et sa réciproque est vraie.', 3),
    ('f507b49e-e4d1-5758-8185-06a0ecf7e022'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Quelle est la première étape de la méthode de résolution ?', 'mcq', '["Définir le système étudié","Projeter sur les axes","Calculer l’accélération","Écrire les conditions initiales"]'::jsonb, 0, 'Sans système défini, le bilan des forces extérieures n’a pas de sens.', 4),
    ('dc6d4da6-29f9-5605-b754-be1bc9ab4253'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Comment calcule-t-on une vitesse limite ?', 'mcq', '["En posant l’accélération égale à zéro dans l’équation","En intégrant deux fois","En dérivant la position","En annulant la vitesse initiale"]'::jsonb, 0, 'À la vitesse limite, le frottement compense exactement le poids : ΣF = 0.', 5),
    ('f1508a98-9bb3-57a8-8114-b898f0a320c1'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'La méthode d’Euler sert à…', 'mcq', '["Résoudre pas à pas une équation différentielle sans solution simple","Mesurer une vitesse expérimentale","Vérifier la troisième loi de Newton","Calculer une énergie"]'::jsonb, 0, 'v(t+Δt) = v(t) + a(t)Δt : c’est ce que fait un tableur ou un script Python.', 6),
    ('a168d58c-7d7e-5ce2-b846-49d2a7b605ff'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Une force intérieure au système figure dans le bilan des forces.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seules les forces extérieures interviennent dans ΣF = m a.', 7),
    ('f6943a7f-25e4-51cd-ad78-d402d329ea68'::uuid, '823ea1bd-5082-5524-9234-8897c77d4d3b'::uuid, 'Au sommet d’un lancer vertical, la vitesse s’annule. Que vaut l’accélération ?', 'mcq', '["Elle vaut g, dirigée vers le bas","Elle est nulle","Elle est dirigée vers le haut","Elle est infinie"]'::jsonb, 0, 'Le poids agit toujours : la force donne la variation de vitesse, pas la vitesse.', 8),
    ('23e95cfb-13cc-559d-a171-73106b3081f2'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'Un champ uniforme est un champ…', 'mcq', '["De même valeur, direction et sens en tout point","Qui ne varie pas dans le temps","Dont la valeur décroît en 1/r²","Qui n’exerce aucune force"]'::jsonb, 0, 'Le champ de pesanteur l’est localement ; le champ de gravitation ne l’est pas à grande échelle.', 1),
    ('46d639f8-1297-528b-8c7a-6dcb1647c25e'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'La trajectoire d’un projectile en chute libre avec vitesse initiale oblique est…', 'mcq', '["Une parabole","Une droite","Un cercle","Une hyperbole"]'::jsonb, 0, 'Mouvement uniforme à l’horizontale, uniformément accéléré à la verticale.', 2),
    ('33d9ef13-9a49-51d2-be83-5c57137a96f9'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'Le mouvement d’un projectile en chute libre dépend de sa masse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'a = g, indépendante de m : plume et bille tombent ensemble dans le vide.', 3),
    ('5fc6849a-8fcb-53de-bde3-9b5337101c7b'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'Que vaut le champ électrique entre deux plaques parallèles distantes de d, sous tension U ?', 'mcq', '["E = U / d","E = U × d","E = d / U","E = q / d"]'::jsonb, 0, 'Il est dirigé de la plaque positive vers la plaque négative.', 4),
    ('afa950fc-9a47-5929-b816-c2e7d4635edf'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'Quand la flèche d’un tir est-elle atteinte ?', 'mcq', '["Quand la composante verticale de la vitesse s’annule","Quand la vitesse totale s’annule","À la moitié de la portée en temps seulement","Au moment du lancer"]'::jsonb, 0, 'La composante horizontale, elle, ne s’annule jamais dans un tir sans frottement.', 5),
    ('5d7a1ab5-8675-52a8-988a-bcafd9fe3b7e'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'L’accélération d’une particule chargée dans un champ électrique uniforme vaut…', 'mcq', '["a = qE/m","a = g","a = qE","a = E/q"]'::jsonb, 0, 'Elle dépend donc de la charge ET de la masse, contrairement à la chute libre.', 6),
    ('96f97022-41ba-5c02-b815-63b19549ac09'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'Pour un tir sans frottement, quel angle donne la portée maximale ?', 'mcq', '["45°","30°","60°","90°"]'::jsonb, 0, 'C’est le compromis entre durée de vol et vitesse horizontale.', 7),
    ('ae06ff81-baec-5cfa-b4d6-fb92ad65557d'::uuid, '3639d919-4019-5f61-9e4b-6c9d35a888d2'::uuid, 'En l’absence de frottement, l’énergie mécanique d’un projectile se conserve.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ec + Ep = constante : cela donne une vitesse sans passer par les équations horaires.', 8),
    ('de30203e-6580-5162-99db-7da82d2e1ee3'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Quelle est l’expression de la vitesse d’un satellite en orbite circulaire de rayon r ?', 'mcq', '["v = √(G M / r)","v = G M / r²","v = √(G M r)","v = 2πr / G"]'::jsonb, 0, 'Elle ne dépend pas de la masse du satellite, seulement de celle de l’astre et du rayon.', 1),
    ('82e49f3b-0243-5907-a18a-9b6bd4f41acc'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Plus l’orbite d’un satellite est basse, plus sa vitesse est…', 'mcq', '["Grande","Petite","Inchangée","Nulle"]'::jsonb, 0, 'v = √(GM/r) : la vitesse décroît quand r augmente.', 2),
    ('0d5846d8-fa36-538c-b88d-dd8c86007a00'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Que dit la troisième loi de Kepler ?', 'mcq', '["T²/a³ est une constante pour tous les satellites d’un même astre","Les orbites sont circulaires","Les aires balayées sont égales en des durées égales","La force varie en 1/r"]'::jsonb, 0, 'C’est la deuxième loi qui énonce la loi des aires.', 3),
    ('aa503d4e-ebb5-5c7f-92a4-8d13f7d3c71f'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Le mouvement circulaire d’un satellite est uniforme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La force est purement centripète : aucune composante tangentielle, donc v constante en valeur.', 4),
    ('a20cc84d-c6e5-5eb8-8ba5-f4f8a1e75b1a'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Quelles conditions doit remplir un satellite géostationnaire ?', 'mcq', '["Orbite équatoriale, même sens de rotation que la Terre, période d’un jour sidéral","Orbite polaire et période de 12 h","Altitude de 400 km","Masse égale à celle de la station spatiale"]'::jsonb, 0, 'Ces trois conditions fixent une orbite unique, à environ 36 000 km d’altitude.', 5),
    ('7656375a-9d34-53fa-b602-79c00bf7450d'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Un astronaute en orbite ne subit plus la gravitation terrestre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est en chute libre permanente avec son vaisseau : c’est l’impesanteur, pas l’absence de gravité.', 6),
    ('8e55f0e9-f02c-5f0c-8aa0-e058f48d615b'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Selon la première loi de Kepler, la trajectoire d’une planète est…', 'mcq', '["Une ellipse dont le Soleil occupe un foyer","Un cercle centré sur le Soleil","Une parabole","Une droite"]'::jsonb, 0, 'Le cercle n’en est que le cas particulier.', 7),
    ('c50625c3-ae21-5f1f-8d7b-b8baa9bc2d8c'::uuid, '706c8792-64a5-5630-a510-462b4959379e'::uuid, 'Comment le champ de gravitation varie-t-il avec la distance à l’astre ?', 'mcq', '["Il décroît en 1/r²","Il est uniforme partout","Il décroît en 1/r","Il croît avec r"]'::jsonb, 0, 'Près du sol, r varie si peu qu’on peut l’assimiler à un champ uniforme.', 8),
    ('526bfc5a-9cb4-5fe9-b417-dae256fa1ca3'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Quelle relation donne le débit volumique ?', 'mcq', '["Dv = S × v","Dv = S / v","Dv = ρ × v","Dv = v / S"]'::jsonb, 0, 'S est l’aire de la section, v la vitesse moyenne du fluide.', 1),
    ('a3526e6f-89ef-5674-9463-beb0e4973afc'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Dans un rétrécissement de canalisation, la vitesse du fluide…', 'mcq', '["Augmente","Diminue","Ne change pas","S’annule"]'::jsonb, 0, 'La conservation du débit impose S₁v₁ = S₂v₂.', 2),
    ('f8e1f2a8-ba53-58ef-9cd1-d799ca3f1cf1'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Que dit la relation de Bernoulli ?', 'mcq', '["P + ½ρv² + ρgz est constante le long d’une ligne de courant","P × V = constante","P = ρgh toujours","La vitesse est constante partout"]'::jsonb, 0, 'C’est une conservation de l’énergie par unité de volume.', 3),
    ('8176a5db-b220-514a-a467-3aa8d1212be4'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Dans un rétrécissement horizontal, la pression du fluide augmente.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Effet Venturi : la vitesse augmente, donc la pression statique diminue.', 4),
    ('9f524795-fde2-58de-b471-099684a43da1'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Un fluide incompressible est un fluide dont…', 'mcq', '["La masse volumique reste constante","La vitesse est constante","La pression est constante","La viscosité est nulle"]'::jsonb, 0, 'C’est une bonne approximation pour les liquides et pour les gaz à faible vitesse.', 5),
    ('7486248f-fc63-527a-9f8e-cbcf1bb24bbc'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Quelle hypothèse la relation de Bernoulli exige-t-elle en plus de l’incompressibilité ?', 'mcq', '["Un écoulement stationnaire et sans frottement","Un écoulement turbulent","Une température constante","Une section constante"]'::jsonb, 0, 'La viscosité réelle provoque des pertes de charge que le modèle ignore.', 6),
    ('806a12b1-bac5-5902-bdc0-bb1609b2f135'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Un écoulement laminaire se fait en couches parallèles qui ne se mélangent pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’écoulement turbulent, chaotique, dissipe bien davantage d’énergie.', 7),
    ('63c559af-8e3e-5e25-8933-fbb6b78118cd'::uuid, '936ea478-0070-5421-9b0c-cee2aedc3f08'::uuid, 'Quel dispositif exploite directement l’effet Venturi ?', 'mcq', '["Le débitmètre à Venturi","Le thermomètre","Le conductimètre","Le pH-mètre"]'::jsonb, 0, 'Comme la trompe à eau ou le carburateur : la dépression y est créée par l’accélération du fluide.', 8),
    ('bf1ea879-c126-527d-b567-70f281fdadad'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'Un système fermé…', 'mcq', '["Échange de l’énergie mais pas de matière","N’échange rien du tout","Échange matière et énergie","Est toujours à l’équilibre"]'::jsonb, 0, 'Le système isolé n’échange rien, le système ouvert échange les deux.', 1),
    ('5ba3726a-2bd3-54ed-87a8-7e062c034ef0'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'Quelle unité employer pour la température dans les formules de thermodynamique ?', 'mcq', '["Le kelvin","Le degré Celsius","Le degré Fahrenheit","Le joule"]'::jsonb, 0, 'Sauf pour les écarts ΔT, où 1 °C et 1 K sont équivalents.', 2),
    ('c2fc02c1-bc26-53c4-ac2d-f859de9d81d8'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'L’énergie interne d’un système comprend son énergie cinétique d’ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne rassemble que les énergies à l’échelle microscopique.', 3),
    ('dcc16920-eb9c-5c31-b146-dd0acb2ec2b4'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'À quoi la température est-elle directement liée à l’échelle microscopique ?', 'mcq', '["À l’énergie cinétique moyenne des entités","Au nombre d’entités","À la masse du système","Au volume occupé"]'::jsonb, 0, 'C’est ce qui donne un sens physique au zéro absolu.', 4),
    ('c44b095e-2fba-5e8c-b5d3-21a6dd5e28f5'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'L’énergie interne est une fonction d’état.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa variation ne dépend que des états initial et final, pas du chemin suivi.', 5),
    ('5c0fc635-8112-5d82-a4b7-89fc2021eb93'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'Que vaut la capacité thermique massique de l’eau liquide ?', 'mcq', '["4185 J·kg⁻¹·K⁻¹","385 J·kg⁻¹·K⁻¹","1000 J·kg⁻¹·K⁻¹","4185 J·K⁻¹"]'::jsonb, 0, 'Une valeur remarquablement élevée, qui fait de l’eau un bon fluide caloporteur.', 6),
    ('b7db6e20-7c7b-5ee9-a2af-c7e0fca17f36'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'Que vaut 25 °C en kelvin ?', 'mcq', '["298,15 K","273,15 K","25 K","248,15 K"]'::jsonb, 0, 'T(K) = θ(°C) + 273,15.', 7),
    ('e5b73e2f-8c62-5149-8607-7974beb8ce75'::uuid, '0c97d355-8cd2-5e70-b00f-c1500c86dcfd'::uuid, 'La pression d’un gaz s’interprète, à l’échelle microscopique, comme…', 'mcq', '["L’effet moyen des chocs des molécules sur les parois","Le poids du gaz","La vitesse moyenne des molécules","Le nombre de molécules par unité de volume"]'::jsonb, 0, 'Les grandeurs macroscopiques sont des moyennes statistiques.', 8),
    ('78dccd0b-19c1-5d75-99f8-681366909741'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Quelle relation donne la variation d’énergie interne d’une phase condensée ?', 'mcq', '["ΔU = m × c × ΔT","ΔU = m × L","ΔU = P × ΔV","ΔU = Q / m"]'::jsonb, 0, 'Valable tant qu’il n’y a pas de changement d’état.', 1),
    ('54378c07-4f3c-5188-9597-6833a4b4c04b'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Pendant un changement d’état d’un corps pur, la température…', 'mcq', '["Reste constante","Augmente régulièrement","Diminue","Varie de façon imprévisible"]'::jsonb, 0, 'L’énergie sert à rompre ou former les interactions entre entités.', 2),
    ('98ebef47-56c5-5a48-a27b-2a5945c81f5d'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Quelle énergie faut-il pour faire fondre une masse m de glace ?', 'mcq', '["Q = m × L_fusion","Q = m × c × ΔT","Q = m × g × h","Q = m × c"]'::jsonb, 0, 'L_fusion de l’eau vaut environ 3,34 × 10⁵ J·kg⁻¹.', 3),
    ('d5882b26-ed6f-5e03-9cac-2e9952ee8829'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Selon la convention adoptée, une énergie reçue par le système est comptée…', 'mcq', '["Positivement","Négativement","Nulle","Selon le sens du travail"]'::jsonb, 0, 'Convention du banquier : ce qui entre est positif.', 4),
    ('fa83f6f8-73e5-5654-8a80-5fd62e53276f'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Le travail est un mode de transfert d’énergie désordonné.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le transfert thermique qui est désordonné ; le travail est ordonné.', 5),
    ('56db745e-2e47-5311-9e89-59b13951096a'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Vaporiser de l’eau coûte plus d’énergie que la fondre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Environ sept fois plus : 2,26 × 10⁶ contre 3,34 × 10⁵ J·kg⁻¹.', 6),
    ('1d2d8c35-062f-5d43-b25a-9a77b6ed3b62'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Que modélise la « valeur en eau » d’un calorimètre ?', 'mcq', '["La capacité thermique du vase lui-même","La masse d’eau à introduire","Les pertes par rayonnement","Le volume utile du calorimètre"]'::jsonb, 0, 'Elle s’ajoute à la masse d’eau dans le bilan Q₁ + Q₂ = 0.', 7),
    ('b04d3a02-39e2-50f7-a297-8bae495af60a'::uuid, '3f72c25a-91ad-5392-90f7-aac094ba21b3'::uuid, 'Pour chauffer de la glace à −10 °C jusqu’à de l’eau à 20 °C, on applique directement ΔU = mcΔT.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut découper : chauffage de la glace, fusion à 0 °C, puis chauffage de l’eau liquide.', 8),
    ('d453f5c7-d47d-5679-90b2-23e5bef8e8a3'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Quel est l’énoncé du premier principe pour un système fermé au repos ?', 'mcq', '["ΔU = W + Q","ΔU = W − Q","ΔU = Q / W","U = W × Q"]'::jsonb, 0, 'C’est la conservation de l’énergie, écrite pour un système qui échange avec l’extérieur.', 1),
    ('198a63db-2d4e-5fd2-80e3-435bfd052f5f'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'W et Q dépendent du chemin suivi, mais leur somme n’en dépend pas.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'ΔU est une fonction d’état : elle ne dépend que des états initial et final.', 2),
    ('436d0efc-aac2-58e7-b64e-4c7506f6b686'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Pour un système isolé, que vaut ΔU ?', 'mcq', '["Zéro","W seulement","Q seulement","Cela dépend de la transformation"]'::jsonb, 0, 'Il n’échange ni travail ni transfert thermique avec l’extérieur.', 3),
    ('2d51b985-0a72-589b-a80a-b9b1fdca8b96'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Que vaut ΔU lors d’une transformation adiabatique ?', 'mcq', '["ΔU = W","ΔU = Q","ΔU = 0","ΔU = W + Q ≠ 0 sans simplification"]'::jsonb, 0, 'Les parois calorifugées annulent Q : c’est l’expérience de Joule.', 4),
    ('4d158c62-5e22-5edd-8ac9-80694ce64043'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Le rendement d’un convertisseur d’énergie peut-il dépasser 1 ?', 'mcq', '["Non, jamais","Oui, avec un bon isolant","Oui, pour une machine thermique","Oui, si le système est isolé"]'::jsonb, 0, 'L’énergie utile ne peut pas dépasser l’énergie fournie.', 5),
    ('7f3b16d1-9044-5c50-915e-2472efd510ed'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Sur un diagramme de chaîne énergétique, que vérifie chaque bloc ?', 'mcq', '["La somme des flèches entrantes égale la somme des sortantes","Les flèches entrantes sont toujours plus nombreuses","Seule l’énergie utile est représentée","Les pertes ne sont pas figurées"]'::jsonb, 0, 'C’est le premier principe mis en dessin.', 6),
    ('ae303eb8-089a-560b-8bcc-b26564162bee'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, 'Le premier principe interdit à la chaleur de passer spontanément du corps froid au corps chaud.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il impose seulement la conservation ; c’est le second principe qui fixe le sens.', 7),
    ('6630ab11-2239-5060-9a53-8e81a21d5c1a'::uuid, '07f6d39e-fd8f-5f7d-a3ec-4561d44cae75'::uuid, '« Consommer de l’énergie » signifie rigoureusement…', 'mcq', '["La convertir en une forme moins utilisable","La détruire","La stocker","La créer à partir de matière"]'::jsonb, 0, 'Rien ne disparaît : le premier principe l’interdit.', 8),
    ('3c97b90d-41ae-5501-9d80-4a99ac7352d3'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Quel mode de transfert thermique ne nécessite aucun support matériel ?', 'mcq', '["Le rayonnement","La conduction","La convection","Aucun"]'::jsonb, 0, 'C’est ainsi que l’énergie du Soleil nous parvient à travers le vide.', 1),
    ('96a876ca-bf7b-55d6-9b43-746f6ac02bfd'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Quelle est l’unité du flux thermique Φ ?', 'mcq', '["Le watt","Le joule","Le kelvin","Le watt par mètre"]'::jsonb, 0, 'Φ = Q/Δt : c’est une puissance.', 2),
    ('a47aa839-9b5b-5a9f-a8a2-2db814d0ddb5'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Quelle est l’expression de la résistance thermique d’une paroi plane ?', 'mcq', '["R_th = e / (λ × S)","R_th = λ × S / e","R_th = e × λ / S","R_th = ΔT × Φ"]'::jsonb, 0, 'Elle croît avec l’épaisseur et décroît avec la conductivité et la surface.', 3),
    ('a4eae58b-5224-57ad-80bd-9d676bb0d6f7'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Des parois placées en série additionnent leurs résistances thermiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’analogie avec les résistances électriques en série est complète.', 4),
    ('246ce321-eb8e-5516-b45b-d141fd892f18'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Un bon isolant thermique possède…', 'mcq', '["Une faible conductivité thermique λ","Une grande conductivité thermique λ","Une grande surface","Une faible épaisseur"]'::jsonb, 0, 'Laine de verre : 0,04 W·m⁻¹·K⁻¹, contre 390 pour le cuivre.', 5),
    ('02ee483e-8068-5384-884d-37cb110bccca'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'Que dit la loi de refroidissement de Newton ?', 'mcq', '["Le flux perdu est proportionnel à l’écart de température","La température décroît linéairement","Le flux est constant","Le refroidissement est instantané"]'::jsonb, 0, 'L’écart de température décroît alors exponentiellement.', 6),
    ('5f534e02-7446-5ccc-929b-f05a0b09fa88'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'La convection suppose un déplacement de matière.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui la distingue de la conduction, qui se fait de proche en proche.', 7),
    ('18cc013c-4262-585d-a247-dc4963014ee8'::uuid, '480ab7fa-5453-573c-affc-73cda5061a37'::uuid, 'En régime stationnaire, la température d’un système…', 'mcq', '["Ne varie plus, car les flux entrant et sortant se compensent","Augmente régulièrement","Décroît exponentiellement","Oscille"]'::jsonb, 0, 'Si un flux l’emporte, le système s’échauffe ou se refroidit.', 8),
    ('465bd2e3-b3f2-5f2d-9c0e-577c4901c407'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Quelle est l’expression du niveau d’intensité sonore ?', 'mcq', '["L = 10 × log(I / I₀)","L = log(I / I₀)","L = 10 × I / I₀","L = 20 × ln(I / I₀)"]'::jsonb, 0, 'Avec I₀ = 1,0 × 10⁻¹² W·m⁻², le seuil d’audibilité.', 1),
    ('a10b233f-485a-5491-985c-8f90a83e034d'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Que vaut le niveau sonore résultant de deux sources identiques de 60 dB chacune ?', 'mcq', '["63 dB","120 dB","60 dB","70 dB"]'::jsonb, 0, 'Les intensités s’additionnent, pas les niveaux : doubler I ajoute 3 dB.', 2),
    ('451be4c5-1804-5009-b08a-8e6bfe2a39be'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Multiplier l’intensité sonore par 10 revient à ajouter…', 'mcq', '["10 dB","3 dB","100 dB","1 dB"]'::jsonb, 0, 'Le facteur 2 correspond, lui, à environ 3 dB.', 3),
    ('b7ad2bcc-073a-5333-abd7-95fd3287c22f'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Doubler la distance à une source sonore ponctuelle fait perdre…', 'mcq', '["6 dB","3 dB","10 dB","12 dB"]'::jsonb, 0, 'L’intensité décroît en 1/d² : quadruplement de la surface, donc division par 4.', 4),
    ('e022302c-4a2f-536b-8a99-f0ddac946995'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'L’atténuation géométrique correspond à une perte réelle d’énergie sonore.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’énergie est seulement répartie sur une sphère plus grande ; c’est l’absorption qui la convertit.', 5),
    ('278ec3af-e2d4-5553-a8dc-4b42c249339f'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Quelle est l’unité de l’intensité sonore I ?', 'mcq', '["W·m⁻²","dB","W","J·m⁻²"]'::jsonb, 0, 'Le décibel mesure le niveau L, pas l’intensité elle-même.', 6),
    ('0639579f-a20e-53fe-bfcb-c5a60ae592eb'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'Un niveau sonore de 0 dB signifie qu’il n’y a aucun son.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela signifie que l’intensité vaut exactement I₀, le seuil d’audibilité.', 7),
    ('7d7b791c-2665-5b71-9ce0-c1553c6858c9'::uuid, '71fe85e9-c9e6-57c7-947b-fe244d5c5c37'::uuid, 'À partir de quel niveau une exposition prolongée endommage-t-elle l’audition ?', 'mcq', '["Environ 85 dB","120 dB","40 dB","60 dB"]'::jsonb, 0, 'Les dommages aux cellules ciliées sont irréversibles.', 8),
    ('cc235644-3419-5682-9a68-1ec820c7e847'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'Quand une source sonore s’approche du récepteur, la fréquence perçue…', 'mcq', '["Augmente","Diminue","Ne change pas","S’annule"]'::jsonb, 0, 'Les fronts d’onde se resserrent : la longueur d’onde perçue diminue.', 1),
    ('a67a4796-909d-5390-886a-7294c5022252'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'L’effet Doppler modifie la fréquence émise par la source.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La source émet toujours la même fréquence : c’est la fréquence REÇUE qui change.', 2),
    ('ffb86aa2-b460-5f41-8b2f-32da744924c6'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'Quelle est la forme approchée du décalage Doppler pour v petite devant c ?', 'mcq', '["Δf / f ≈ v / c","Δf / f ≈ c / v","Δf ≈ v × c","Δf / f ≈ v² / c²"]'::jsonb, 0, 'C’est la relation utilisée dans la plupart des exercices.', 3),
    ('fb6f6207-6d42-5425-833b-776c83b2776a'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'Pourquoi le décalage vaut-il 2v/c pour un radar routier ?', 'mcq', '["Le véhicule joue successivement le rôle de récepteur puis de source","La vitesse est doublée par la réflexion","L’onde parcourt deux fois la distance","Le radar émet deux ondes"]'::jsonb, 0, 'L’effet Doppler s’applique donc deux fois de suite.', 4),
    ('3b76a576-3d78-5bcc-824e-37cac1cbf8d9'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'Qu’observe-t-on sur le spectre d’une étoile qui s’éloigne de nous ?', 'mcq', '["Un décalage vers le rouge","Un décalage vers le bleu","Aucun décalage","Une disparition des raies"]'::jsonb, 0, 'Le redshift des galaxies lointaines a établi l’expansion de l’Univers.', 5),
    ('d804630e-d332-5a8e-a107-c3e95459cc50'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'La célérité de l’onde dépend-elle du mouvement de la source ?', 'mcq', '["Non, elle ne dépend que du milieu","Oui, elle augmente si la source approche","Oui, elle diminue si la source s’éloigne","Elle devient infinie au mur du son"]'::jsonb, 0, 'Seules la fréquence et la longueur d’onde perçues sont modifiées.', 6),
    ('4385f97c-75fd-50c4-8763-2104d524c4f6'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'Une source se déplaçant perpendiculairement à la ligne de visée produit un effet Doppler nul.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Seule la composante radiale de la vitesse compte.', 7),
    ('52609f6a-18d3-55e5-87fa-af37c2962961'::uuid, '8e4699a8-5f21-5ae1-b1c9-2f87e4e47d45'::uuid, 'L’échographie Doppler mesure…', 'mcq', '["La vitesse du sang dans un vaisseau","La température du corps","L’épaisseur d’un organe","La composition du sang"]'::jsonb, 0, 'Elle exploite la réflexion des ultrasons sur les globules rouges en mouvement.', 8),
    ('074bbc55-5900-5b3f-b4f5-b2b9ab7dd755'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'À quelle condition une onde est-elle notablement diffractée ?', 'mcq', '["Quand la dimension de l’ouverture est de l’ordre de sa longueur d’onde","Quand l’ouverture est très grande","Quand la fréquence est très élevée","Quand le milieu est absorbant"]'::jsonb, 0, 'Plus l’ouverture est petite devant λ, plus l’étalement est marqué.', 1),
    ('6ca571f9-0375-57d0-95da-830d6d3ca862'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'Quelle relation donne le demi-angle de diffraction ?', 'mcq', '["θ = λ / a","θ = a / λ","θ = λ × a","θ = 2λ / D"]'::jsonb, 0, 'θ est exprimé en radians ; la tache centrale a pour largeur L = 2λD/a.', 2),
    ('6da0343e-e48f-51f7-b8e5-f759995c6d9c'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'Réduire la largeur de la fente…', 'mcq', '["Élargit la tache centrale","Rétrécit la tache centrale","Ne change rien","Supprime la diffraction"]'::jsonb, 0, 'θ = λ/a : l’étalement est inversement proportionnel à la largeur.', 3),
    ('dc3e5dcf-c024-5201-ac36-cd934f3fdfb3'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'La diffraction modifie la longueur d’onde de l’onde diffractée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ni la fréquence, ni la longueur d’onde, ni la célérité ne changent : seule la répartition spatiale change.', 4),
    ('8f97cf66-4622-5856-82f8-6754c110aacc'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'Pourquoi entend-on surtout les basses depuis la pièce voisine ?', 'mcq', '["Leur grande longueur d’onde se diffracte mieux","Elles sont émises plus fort","Elles traversent les murs sans être absorbées","Les aigus sont réfléchis par le plafond"]'::jsonb, 0, 'La diffraction est d’autant plus marquée que λ est grande devant l’ouverture.', 5),
    ('0fb01e18-99d4-5624-9335-be92c34443f6'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'Quelle largeur a la tache centrale de diffraction sur un écran à la distance D ?', 'mcq', '["L = 2λD / a","L = λD / a","L = λ / (aD)","L = aD / λ"]'::jsonb, 0, 'C’est le double de Dθ, la tache s’étalant de part et d’autre de l’axe.', 6),
    ('f827de6f-15ae-52f5-854b-d1aaa71a4647'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'Le tracé de L en fonction de 1/a doit donner une droite passant par l’origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'De coefficient directeur 2λD : c’est la vérification quantitative du modèle.', 7),
    ('32334b21-44e8-5599-97f6-5b86de6dcbe8'::uuid, '80cc219c-aee4-55a0-8fe2-fddb5e2f1d1a'::uuid, 'La diffraction limite la résolution des télescopes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Deux étoiles proches donnent deux taches qui se recouvrent — d’où l’intérêt des grands diamètres.', 8),
    ('ccf7d7a1-89f0-590c-815b-cde054d7202b'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Quelle condition deux sources doivent-elles remplir pour interférer de façon stable ?', 'mcq', '["Être cohérentes : même fréquence, déphasage constant","Avoir la même intensité","Être placées à la même distance de l’écran","Émettre en lumière blanche"]'::jsonb, 0, 'En pratique, on dédouble une source unique : deux lampes distinctes ne suffisent pas.', 1),
    ('2a152e03-5cfc-5958-9243-1f0efa8ac430'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Quelle est la condition d’interférences destructives ?', 'mcq', '["δ = (k + ½) λ","δ = k λ","δ = λ / 2 uniquement","δ = 0"]'::jsonb, 0, 'Les ondes arrivent alors en opposition de phase.', 2),
    ('cdef69d5-e71b-503b-95d2-5e68bc0048b8'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Quelle est l’expression de l’interfrange dans le dispositif des fentes d’Young ?', 'mcq', '["i = λD / b","i = bD / λ","i = λ / (bD)","i = 2λD / b"]'::jsonb, 0, 'D est la distance à l’écran, b l’écart entre les deux fentes.', 3),
    ('72b29df8-fc75-5276-960c-338743cae8a7'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Lors d’interférences destructives, l’énergie lumineuse est détruite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est redistribuée vers les franges brillantes : le bilan total est inchangé.', 4),
    ('d166dd40-1979-5fc9-9c5c-9017862bcec0'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Que se passe-t-il si l’on éclaire les fentes d’Young en lumière blanche ?', 'mcq', '["Chaque couleur donne son interfrange, les franges sont irisées","On n’observe rien","Toutes les franges restent blanches","Les franges disparaissent au centre"]'::jsonb, 0, 'Seule la frange centrale, où δ = 0 pour toutes les couleurs, reste blanche.', 5),
    ('c888db3d-4c14-521b-a2ef-6210aefbdf94'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Les couleurs d’une bulle de savon proviennent…', 'mcq', '["D’interférences entre les rayons réfléchis sur ses deux faces","De pigments dissous dans le savon","De la diffraction sur les bords","De l’effet Doppler"]'::jsonb, 0, 'Elles changent avec l’angle de vue, ce qu’aucun pigment ne fait.', 6),
    ('3972096f-4e54-549b-969c-9aeeee113c81'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'L’interfrange est proportionnel à la longueur d’onde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'i = λD/b : c’est ce qui permet de mesurer λ avec une simple règle.', 7),
    ('65b3666e-ce56-5f5d-b56a-c4c0fae8d759'::uuid, '738d8743-a78a-58a1-adc1-198732b318a1'::uuid, 'Sur quel principe repose un casque à réduction active de bruit ?', 'mcq', '["L’émission d’une onde en opposition de phase avec le bruit","L’absorption du son par une mousse","La diffraction du son","L’effet Doppler"]'::jsonb, 0, 'C’est une interférence destructive provoquée volontairement.', 8),
    ('955e7690-f9a7-5be1-9dea-09b673b3a0b4'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Où se forme l’image d’un objet situé à l’infini à travers une lentille convergente ?', 'mcq', '["Dans le plan focal image","Au centre optique","Dans le plan focal objet","À l’infini également"]'::jsonb, 0, 'Les rayons arrivent parallèles entre eux et convergent en un point de ce plan.', 1),
    ('baf40ca2-6638-5982-8180-891455883ded'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Une lunette est dite afocale quand…', 'mcq', '["Le foyer image de l’objectif est confondu avec le foyer objet de l’oculaire","Les deux lentilles ont la même focale","L’objectif est divergent","L’image finale se forme sur la rétine"]'::jsonb, 0, 'L’image finale est alors rejetée à l’infini : l’œil observe sans accommoder.', 2),
    ('768d9143-d70b-5c72-8591-fd9b49d2e50b'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Quelle est l’expression du grossissement d’une lunette afocale ?', 'mcq', '["G = f′₁ / f′₂","G = f′₂ / f′₁","G = f′₁ × f′₂","G = 1 / (f′₁ f′₂)"]'::jsonb, 0, 'Objectif de grande focale, oculaire de courte focale.', 3),
    ('ef045a51-a5c3-524e-9d0c-1aa09d7ca7f0'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Un rayon passant par le centre optique d’une lentille mince…', 'mcq', '["N’est pas dévié","Émerge parallèle à l’axe","Passe par le foyer image","Est réfléchi"]'::jsonb, 0, 'C’est le premier des trois rayons particuliers à connaître.', 4),
    ('f2fff9a8-3863-54aa-9a94-2bb6992593d4'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'L’image donnée par une lunette astronomique est renversée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans importance en astronomie ; une lunette terrestre ajoute un redresseur.', 5),
    ('fd9891f0-89bd-5afd-b9f3-83106e212f2f'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Quelle est la relation de conjugaison d’une lentille mince ?', 'mcq', '["1/OA′ − 1/OA = 1/f′","1/OA′ + 1/OA = 1/f′","OA′ − OA = f′","OA′ × OA = f′²"]'::jsonb, 0, 'Les mesures y sont algébriques, comptées à partir du centre optique.', 6),
    ('985dddc0-81bd-588f-bdc1-8f20d8f5a14e'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Qu’est-ce qui limite réellement les performances d’une lunette ?', 'mcq', '["Le diamètre de son objectif","Le grossissement de l’oculaire","La longueur du tube","Le poids de l’instrument"]'::jsonb, 0, 'Il fixe la lumière collectée et la limite de diffraction, donc le pouvoir séparateur.', 7),
    ('1f938439-d994-5b9f-b47e-7045004bc3a9'::uuid, 'd62979bd-6f2f-594d-ae96-5a7c7b2b3061'::uuid, 'Un grandissement négatif signifie que l’image est…', 'mcq', '["Renversée","Plus petite","Virtuelle","Située avant la lentille"]'::jsonb, 0, 'Le signe porte sur le sens, la valeur absolue sur la taille.', 8),
    ('193c1996-4d2c-52d3-b3cf-a55a4d864b2b'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Quelle est l’expression de l’énergie d’un photon ?', 'mcq', '["E = h c / λ","E = h λ","E = c / (h λ)","E = ½ h ν²"]'::jsonb, 0, 'Soit E = hν : elle ne dépend que de la fréquence.', 1),
    ('37f3c48d-cd40-5190-bbb8-003ffb5847f8'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Que vaut la constante de Planck ?', 'mcq', '["6,63 × 10⁻³⁴ J·s","1,60 × 10⁻¹⁹ C","3,00 × 10⁸ m·s⁻¹","9,81 J·s"]'::jsonb, 0, '1,60 × 10⁻¹⁹ C est la charge élémentaire, qui définit l’électronvolt.', 2),
    ('bd5024d4-d3d1-5dc1-bf07-bc67290b2330'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Une lumière rouge très intense peut-elle arracher des électrons à un métal de seuil situé dans l’ultraviolet ?', 'mcq', '["Non, quelle que soit son intensité","Oui, si elle est assez intense","Oui, en attendant assez longtemps","Cela dépend de la durée d’exposition"]'::jsonb, 0, 'Un électron reçoit un photon entier ou rien : il faut hν > W₀.', 3),
    ('3a3b4aa7-d587-533b-a836-ee690a34e27a'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'L’effet photoélectrique s’explique par le modèle ondulatoire de la lumière.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le modèle ondulatoire prédirait une accumulation progressive d’énergie, ce qu’on n’observe pas.', 4),
    ('2be38865-2c47-5840-8fdf-a322d60ec566'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Que traduit la dualité onde-corpuscule ?', 'mcq', '["La lumière se décrit comme une onde ou comme un flot de photons selon le phénomène","La lumière change de nature avec la fréquence","Les photons sont des ondes de matière","Seul le modèle corpusculaire est correct"]'::jsonb, 0, 'Propagation : onde. Échanges d’énergie : corpuscule.', 5),
    ('dab4f05b-dbed-58b8-bc02-dccac1c162c2'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Pourquoi un atome n’émet-il que certaines longueurs d’onde ?', 'mcq', '["Parce que ses niveaux d’énergie sont quantifiés","Parce que sa masse est fixe","Parce qu’il ne reçoit que certains photons","Parce que sa température est constante"]'::jsonb, 0, 'Il n’échange que la différence entre deux niveaux : ΔE = hν.', 6),
    ('9e116bf7-0e16-5d0e-bd85-c33a6674c537'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Un spectre de raies permet d’identifier les éléments présents dans une étoile.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque élément possède son propre jeu de longueurs d’onde absorbées et émises.', 7),
    ('b24838fa-1e43-5d29-aac3-c4d1efac0509'::uuid, '1a3ef33e-60fd-5ba2-b103-4ff6eccaa1e4'::uuid, 'Sur quel phénomène repose le fonctionnement d’un laser ?', 'mcq', '["L’émission stimulée","L’effet photoélectrique","L’effet Doppler","La diffraction"]'::jsonb, 0, 'Elle donne un faisceau monochromatique, directif et cohérent.', 8),
    ('40f0ba1f-ee30-56ce-8c29-524da6ca4bf0'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'Quelle relation lie la charge d’un condensateur à la tension à ses bornes ?', 'mcq', '["q = C × u","q = u / C","q = C / u","q = C × u²"]'::jsonb, 0, 'C est la capacité, exprimée en farads.', 1),
    ('64f3e4fd-4247-54d6-8b33-df137a632dfb'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'Que vaut la constante de temps d’un dipôle RC ?', 'mcq', '["τ = R × C","τ = R / C","τ = C / R","τ = RC²"]'::jsonb, 0, 'Elle est homogène à un temps : Ω × F = s.', 2),
    ('ce641d8f-b26b-50e6-83d5-e1094e4f1e77'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'À t = τ lors de la charge, quel pourcentage de la tension finale est atteint ?', 'mcq', '["63 %","50 %","37 %","99 %"]'::jsonb, 0, 'Lors de la décharge, il reste symétriquement 37 % de la tension initiale.', 3),
    ('e61458e9-8f71-5e6e-833d-53f7e6452cbd'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'Au bout de combien de constantes de temps le régime permanent est-il pratiquement atteint ?', 'mcq', '["Environ 5τ","Environ τ","Environ 2τ","Jamais"]'::jsonb, 0, 'La tangente à l’origine, elle, coupe l’asymptote à t = τ.', 4),
    ('967e260b-e987-5a0b-97b9-daed6c36a5a0'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'En régime permanent, un condensateur se comporte comme un interrupteur ouvert.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'i = C du/dt : sans variation de tension, aucun courant ne le traverse.', 5),
    ('64eee8da-6a33-5688-a232-ea5c01003ae8'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'Quelle est l’expression de l’énergie stockée dans un condensateur ?', 'mcq', '["E = ½ C u²","E = C u","E = ½ u² / C","E = C² u"]'::jsonb, 0, 'C’est cette énergie qu’un flash restitue en quelques millisecondes.', 6),
    ('90940d3c-f886-5808-b75a-4be5c70f3521'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'Sur quel principe repose un écran tactile capacitif ?', 'mcq', '["Le doigt modifie localement la capacité de la grille d’électrodes","Le doigt ferme un circuit électrique","Le doigt chauffe la surface","Le doigt réfléchit un faisceau lumineux"]'::jsonb, 0, 'La variation de capacité est convertie en position par l’électronique.', 7),
    ('76dfa35d-c352-5d91-8ffc-680624742e5a'::uuid, 'a52b2797-128a-5477-815d-c5203f6cea74'::uuid, 'La décharge d’un condensateur suit la même loi mathématique que la décroissance radioactive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Deux phénomènes sans rapport physique, une même équation exponentielle.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('physique-chimie');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('physique-chimie')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 252 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 252 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
